import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and represents a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return false;
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate date format and reality
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total amount (before VAT) for a line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate subtotal and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
  }
  return {
    subtotal: roundCents(subtotal),
    total: roundCents(subtotal),
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = [];
  let found = false;

  for (const line of invoice.lines) {
    if (line.sku === sku) {
      found = true;
      newLines.push({
        sku: line.sku,
        name: line.name,
        qty: line.qty + qty,
        unitPrice: line.unitPrice,
        vatRate: line.vatRate,
      });
    } else {
      newLines.push({ ...line });
    }
  }

  if (!found) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  if (newLines.length === invoice.lines.length) return fail('LINE_NOT_FOUND');
  if (newLines.length === 0) return fail('NO_LINES');

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ status: string }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NOT_DRAFT: 'This operation is only allowed on draft invoices.',
  NO_LINES: 'An invoice must have at least one line.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

